code.source:
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *ticket = malloc(sizeof(int));
    if (ticket == NULL) return 1;
    *ticket = 101;
    printf("Ticket: %d\n", *ticket);

    free(ticket);
    ticket = NULL;

    if (ticket != NULL) {
        printf("Still have ticket %d\n", *ticket);
    } else {
        printf("Ticket returned, pointer set to NULL\n");
    }

    free(ticket);
    printf("free(NULL) is safe and does nothing\n");
    return 0;
}

